import"./chunk-VC46IEJQ.js";var e=(o,h,s,a,i,l,t,r,n)=>({name:{en:o,zh:h},desc:{en:s[0],zh:s[1]},tour:{en:a[0],zh:a[1]},source:{confidence:i,refs:l,book:{en:t[0],zh:t[1]},unknown:{en:r[0],zh:r[1]},interpretation:{en:n[0],zh:n[1]}}}),d={id:"kayakayanaya",intro:{en:"Tall Trees Town is a port on the south-west coast of Walano in the Summer Isles, shaded by enormous trees. The novels name it only as a ship's home port, so this is a gentle, openly interpretive scene.",zh:"\u9AD8\u6811\u9547\u662F\u76DB\u590F\u7FA4\u5C9B\u4E2D\u74E6\u62C9\u8BFA\u5C9B\u897F\u5357\u5CB8\u7684\u6E2F\u53E3\uFF0C\u63A9\u6620\u5728\u53C2\u5929\u5DE8\u6811\u4E4B\u4E0B\u3002\u5C0F\u8BF4\u53EA\u5728\u63D0\u5230\u8239\u7C4D\u65F6\u70B9\u8FC7\u5B83\u7684\u540D\u5B57\uFF0C\u6240\u4EE5\u672C\u573A\u666F\u662F\u4E00\u4EFD\u6E29\u548C\u3001\u660E\u786E\u51FA\u4E8E\u60F3\u8C61\u7684\u8BE0\u91CA\u3002"},notes:{en:"From the novels: Summer Islanders sail swan ships and wear feather cloaks, and Tall Trees Town is named as a home port. From the companion book: the town lies on Walano and is shaded by the Talking Trees, huge trees on whose trunks feather-robed priestesses carve the islanders' history, laws and songs. The canopy houses, walkways, market, banners and harbour plan are invented for this atlas.",zh:"\u5C0F\u8BF4\u53EF\u636E\uFF1A\u76DB\u590F\u7FA4\u5C9B\u4EBA\u9A7E\u9A76\u5929\u9E45\u8239\u3001\u62AB\u7FBD\u6BDB\u6597\u7BF7\uFF0C\u9AD8\u6811\u9547\u66FE\u4F5C\u4E3A\u8239\u7C4D\u6E2F\u88AB\u63D0\u53CA\u3002\u8BBE\u5B9A\u96C6\u53EF\u636E\uFF1A\u5C0F\u9547\u4F4D\u4E8E\u74E6\u62C9\u8BFA\u5C9B\uFF0C\u7531\u201C\u8A00\u8BED\u4E4B\u6811\u201D\u906E\u836B\uFF1B\u8FD9\u4E9B\u5DE8\u6811\u7684\u6811\u5E72\u4E0A\uFF0C\u8EAB\u62AB\u7FBD\u888D\u7684\u5973\u796D\u53F8\u523B\u4E0B\u4E86\u5C9B\u6C11\u7684\u5386\u53F2\u3001\u5F8B\u6CD5\u4E0E\u6B4C\u8C23\u3002\u6797\u51A0\u5C4B\u820D\u3001\u6808\u9053\u3001\u96C6\u5E02\u3001\u5F69\u65D7\u4E0E\u6E2F\u53E3\u5E03\u5C40\u5747\u4E3A\u672C\u56FE\u96C6\u81EA\u62DF\u3002"},tour:["harbour","shore-market","giant-trees","canopy-houses","rope-walkways","feather-banners"],sources:[{ref:"affc",checked:"memory",note:{en:"Samwell sails on the Cinnamon Wind, a swan ship from Tall Trees Town, whose Summer Islander crew wear feathered cloaks; recalled, not re-read.",zh:"\u5C71\u59C6\u642D\u4E58\u6765\u81EA\u9AD8\u6811\u9547\u7684\u5929\u9E45\u8239\u201C\u8089\u6842\u98CE\u201D\u53F7\uFF0C\u8239\u4E0A\u7684\u76DB\u590F\u7FA4\u5C9B\u6C34\u624B\u62AB\u7740\u7FBD\u6BDB\u6597\u7BF7\uFF1B\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Wiki search summaries citing the companion: the town on Walano's south-west coast and the Talking Trees carved by feather-robed priestesses. The book itself was not checked.",zh:"\u636E\u5F15\u7528\u8BBE\u5B9A\u96C6\u7684\u7EF4\u57FA\u641C\u7D22\u6458\u8981\uFF1A\u5C0F\u9547\u4F4D\u4E8E\u74E6\u62C9\u8BFA\u5C9B\u897F\u5357\u5CB8\uFF1B\u8A00\u8BED\u4E4B\u6811\u4E0A\u7684\u523B\u6587\u51FA\u81EA\u8EAB\u62AB\u7FBD\u888D\u7684\u5973\u796D\u53F8\u4E4B\u624B\u3002\u672A\u67E5\u9605\u539F\u4E66\u3002"}}],landmarks:{"giant-trees":e("Talking Trees","\u8A00\u8BED\u4E4B\u6811",["Enormous buttressed trees shading the town, their trunks carved with the islanders' history, laws and songs.","\u677F\u6839\u7C97\u58EE\u7684\u53C2\u5929\u5DE8\u6811\u4E3A\u5168\u9547\u906E\u836B\uFF0C\u6811\u5E72\u4E0A\u523B\u7740\u5C9B\u6C11\u7684\u5386\u53F2\u3001\u5F8B\u6CD5\u4E0E\u6B4C\u8C23\u3002"],["The Summer Islanders' whole history is carved into these trunks.","\u76DB\u590F\u7FA4\u5C9B\u4EBA\u7684\u5168\u90E8\u5386\u53F2\u90FD\u523B\u5728\u8FD9\u4E9B\u6811\u5E72\u4E0A\u3002"],"medium",["twoiaf"],["The Talking Trees are huge trees shading the town; priestesses in feathered robes carve history, laws and songs on them.","\u8A00\u8BED\u4E4B\u6811\u662F\u4E3A\u5C0F\u9547\u906E\u836B\u7684\u5DE8\u6811\uFF1B\u8EAB\u62AB\u7FBD\u888D\u7684\u5973\u796D\u53F8\u5728\u6811\u4E0A\u523B\u4E0B\u5386\u53F2\u3001\u5F8B\u6CD5\u4E0E\u6B4C\u8C23\u3002"],["Species and real heights.","\u6811\u79CD\u4E0E\u771F\u5B9E\u9AD8\u5EA6\u3002"],["Twenty-two trunks 50 to 75 metres tall with broad crowns; carvings are suggested, not drawn.","\u4E8C\u5341\u4E8C\u682A\u4E94\u5341\u81F3\u4E03\u5341\u4E94\u7C73\u9AD8\u7684\u5DE8\u6811\uFF0C\u6811\u51A0\u5BBD\u9614\uFF1B\u523B\u6587\u53EA\u4F5C\u6697\u793A\uFF0C\u672A\u5177\u4F53\u63CF\u753B\u3002"]),"canopy-houses":e("Canopy Houses","\u6797\u51A0\u5C4B\u820D",["Thatched huts on round platforms circling the trunks, high above the ground.","\u5706\u5F62\u5E73\u53F0\u73AF\u7ED5\u6811\u5E72\uFF0C\u53F0\u4E0A\u5EFA\u7740\u8305\u9876\u5C0F\u5C4B\uFF0C\u9AD8\u60AC\u4E8E\u5730\u9762\u4E4B\u4E0A\u3002"],["Imagined homes raised into the branches, cool and out of the wet.","\u60F3\u8C61\u4E2D\u67B6\u5728\u679D\u5934\u7684\u5C4B\u820D\uFF0C\u51C9\u723D\u53C8\u4E0D\u53D7\u6F6E\u6E7F\u3002"],"low",["twoiaf"],["Nothing describes houses in the trees.","\u6CA1\u6709\u4EFB\u4F55\u8BB0\u8F7D\u63D0\u5230\u6811\u4E0A\u7684\u623F\u5C4B\u3002"],["How the townsfolk really live.","\u9547\u6C11\u5B9E\u9645\u7684\u5C45\u4F4F\u65B9\u5F0F\u3002"],["Two platform levels with two or three huts each; invented.","\u4E24\u5C42\u5E73\u53F0\uFF0C\u6BCF\u5C42\u4E24\u4E09\u95F4\u5C0F\u5C4B\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"rope-walkways":e("Rope Walkways","\u60AC\u7D22\u6808\u9053",["Railed plank walks joining the platforms from tree to tree.","\u5E26\u6276\u624B\u7684\u6728\u677F\u6808\u9053\uFF0C\u628A\u4E00\u5EA7\u5EA7\u5E73\u53F0\u7531\u6811\u5230\u6811\u8FDE\u63A5\u8D77\u6765\u3002"],["A web of walkways lets people cross town without touching the ground.","\u6808\u9053\u5982\u7F51\uFF0C\u4EBA\u4EEC\u4E0D\u5FC5\u843D\u5730\u4FBF\u80FD\u7A7F\u884C\u5168\u9547\u3002"],"low",["twoiaf"],["Not described anywhere.","\u4EFB\u4F55\u8D44\u6599\u90FD\u672A\u63D0\u53CA\u3002"],["Whether walkways exist and their form.","\u6808\u9053\u662F\u5426\u5B58\u5728\u53CA\u5176\u5F62\u6001\u3002"],["Straight railed plank spans between platforms.","\u5E73\u53F0\u4E4B\u95F4\u7B14\u76F4\u3001\u5E26\u680F\u6746\u7684\u6728\u677F\u6865\u3002"]),harbour:e("Harbour","\u6E2F\u53E3",["A warm bay with a long boardwalk and piers where swan ships tie up.","\u6E29\u6696\u7684\u6D77\u6E7E\uFF0C\u957F\u957F\u7684\u6728\u6808\u9053\u4E0E\u6808\u6865\u8FB9\u6CCA\u7740\u5929\u9E45\u8239\u3002"],["Swan ships from Tall Trees Town sail as far as Oldtown.","\u9AD8\u6811\u9547\u7684\u5929\u9E45\u8239\u8FDC\u822A\u81F3\u65E7\u9547\u3002"],"medium",["affc","twoiaf"],["Tall Trees Town is a home port for Summer Isles swan ships.","\u9AD8\u6811\u9547\u662F\u76DB\u590F\u7FA4\u5C9B\u5929\u9E45\u8239\u7684\u8239\u7C4D\u6E2F\u4E4B\u4E00\u3002"],["The harbour's form.","\u6E2F\u53E3\u5F62\u6001\u3002"],["A long timber boardwalk with nine piers.","\u4E00\u6761\u957F\u6728\u6808\u9053\u4E0E\u4E5D\u5EA7\u6808\u6865\u3002"]),"shore-market":e("Shore Market","\u6EE8\u6D77\u96C6\u5E02",["Stilt-houses and stalls along the beach, in the shade between the trunks and the sea.","\u6CBF\u6D77\u6EE9\u642D\u5EFA\u7684\u9AD8\u811A\u5C4B\u4E0E\u644A\u4F4D\uFF0C\u9690\u5728\u6811\u5E72\u4E0E\u6D77\u6C34\u4E4B\u95F4\u7684\u836B\u51C9\u91CC\u3002"],["Between trees and tide, goods change hands under thatch.","\u5DE8\u6811\u4E0E\u6F6E\u6C34\u4E4B\u95F4\uFF0C\u8305\u6A90\u4E0B\u8D27\u7269\u6613\u624B\u3002"],"low",["twoiaf"],["Not described.","\u672A\u89C1\u63CF\u5199\u3002"],["Where trade takes place.","\u4EA4\u6613\u5728\u4F55\u5904\u8FDB\u884C\u3002"],["Scattered thatched houses along the boardwalk; invented.","\u6CBF\u6808\u9053\u6563\u5E03\u7684\u8305\u9876\u623F\u5C4B\uFF1B\u4E3A\u81EA\u62DF\u3002"]),"feather-banners":e("Feather Banners","\u7FBD\u65D7",["Bright red, green and gold banners hung from the trees, echoing the islanders' feather cloaks.","\u6811\u95F4\u60AC\u6302\u7684\u7EA2\u3001\u7EFF\u3001\u91D1\u8272\u65D7\u5E1C\uFF0C\u547C\u5E94\u5C9B\u6C11\u7684\u7FBD\u6BDB\u6597\u7BF7\u3002"],["Feathers mark the islanders; here they colour the trees.","\u7FBD\u6BDB\u662F\u5C9B\u6C11\u7684\u6807\u5FD7\uFF1B\u5728\u8FD9\u91CC\uFF0C\u5B83\u4EEC\u4E3A\u6811\u6728\u6DFB\u5F69\u3002"],"low",["affc","twoiaf"],["Summer Islanders wear feather cloaks, and their priestesses feathered robes.","\u76DB\u590F\u7FA4\u5C9B\u4EBA\u62AB\u7FBD\u6BDB\u6597\u7BF7\uFF0C\u5973\u796D\u53F8\u8EAB\u7740\u7FBD\u888D\u3002"],["Whether banners are hung like this.","\u662F\u5426\u6709\u8FD9\u6837\u60AC\u6302\u65D7\u5E1C\u7684\u4E60\u4FD7\u3002"],["Coloured pennants stand in for feathers; invented.","\u4EE5\u5F69\u65D7\u4EE3\u6307\u7FBD\u6BDB\uFF1B\u4E3A\u81EA\u62DF\u3002"])}};export{d as default};
